/* ===================== Helpers ===================== */
const DAY = 864e5;
function pad(n){ return (n < 10 ? '0' : '') + n; }
function isoOf(d){ return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
function parseIso(s){ const p = String(s || '').split('-').map(Number); return new Date(p[0] || 2026, (p[1] || 1) - 1, p[2] || 1); }
function addDays(s, n){ const d = parseIso(s); d.setDate(d.getDate() + n); return isoOf(d); }
function diffDays(a, b){ return Math.round((parseIso(b) - parseIso(a)) / DAY); }
function fmtDate(s){ if (!s) return '—'; return parseIso(s).toLocaleDateString('en-AU', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }); }
function fmtShort(s){ if (!s) return '—'; return parseIso(s).toLocaleDateString('en-AU', { day: 'numeric', month: 'short' }); }
function fmtMonth(s){ return parseIso(s).toLocaleDateString('en-AU', { month: 'short', year: '2-digit' }); }
function fmtDT(ms){ return new Date(ms).toLocaleString('en-AU', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' }); }
function money(n, dec){ const v = Math.round((n || 0) * 100) / 100; const neg = v < 0; const s = Math.abs(v).toLocaleString('en-AU', { minimumFractionDigits: dec ? 2 : 0, maximumFractionDigits: dec ? 2 : 0 }); return (neg ? '−' : '') + 'A$' + s; }
function pctOf(n, d){ return d > 0 ? Math.round(n / d * 100) + '%' : '—'; }
function clamp(v, a, b){ return Math.max(a, Math.min(b, v)); }
function initialsOf(name){ return String(name || '?').split(' ').filter(Boolean).map(w => w[0]).join('').slice(0, 2).toUpperCase(); }
function firstName(name){ return String(name || '').split(' ')[0]; }
function sum(list, f){ return list.reduce((a, x) => a + (f ? f(x) : x), 0); }
function upd(list, id, patch){ return list.map(x => x.id === id ? Object.assign({}, x, patch) : x); }
function byId(list, id){ return list.find(x => x.id === id); }
let _uid = 1000;
function uid(p){ _uid += 7919; return p + '_' + ((_uid * 2654435761) % 2176782336).toString(36); }
function monthStart(s){ const d = parseIso(s); d.setDate(1); return isoOf(d); }
function addMonths(s, n){ const d = parseIso(s); d.setMonth(d.getMonth() + n); d.setDate(1); return isoOf(d); }

