    const pendingL = db.listings.find(l => l.hostId === this.hostId() && l.status === 'pending_review'); if (pendingL) add('Program approves your listing now', 'Skips the few-second simulated review', () => this.demoApproveListing(pendingL.id));
    const jordanBusy = !!st || !!openReq || db.requests.some(r => r.participantId === this.csId() && r.status === 'accepted');
    if (listing && !jordanBusy) add('Jordan sends a stay request', '4 weeks at ' + listing.title, () => this.submitRequest({ listingId: listing.id, forms: { rq_start: listing.fromDate > today ? listing.fromDate : today, rq_weeks: '4', rq_ack: true } }));
    if (openReq && openReq.status === 'clarification') add('Jordan replies to your question', 'Answers your clarification question', () => this.sendClarification(openReq.id, 'Weekdays I\'m at TAFE until about 3pm, then I study at home. No pets, and I\'m happy to help walk the kelpie!'));
