      const inc = db.incidents.find(i => i.stayId === st.id && i.raisedBy === 'host' && i.status === 'open'); if (inc) add('Jordan responds to your concern', 'Adds their account to the record', () => this.respondIncident(inc.id, 'Sorry about Tuesday: a friend had music on while we studied. I\'ve set a 9:45pm reminder so it won\'t happen again.'));
      if (!db.extensions.some(e => e.stayId === st.id && e.status === 'pending')) add('Jordan requests a 2-week extension', 'You decide from Stays', () => this.submitExtension({ ext_weeks: '2', ext_reason: 'My TAFE placement runs two more weeks and the share house I\'m moving to is free from the 15th.' }));
