  this._lifecycleRunning = true; const q = []; const step = (ms, label, fn) => q.push([ms, label, fn]);
  step(0, 'Jordan requests the room', () => this.submitRequest({ listingId: listing.id, forms: { rq_start: listing.fromDate > today ? listing.fromDate : today, rq_weeks: '4', rq_ack: true } }));
  step(1900, 'Priya accepts', () => { const r = this.state.db.requests.find(x => x.participantId === this.csId() && x.status === 'pending'); if (r) this.acceptRequest(r.id); });
  step(3800, 'Jordan confirms the agreement', () => this.csConfirmAgreement());
  step(5700, 'Priya confirms check-in', () => { const st = this.currentStay(); if (st && st.status === 'confirmed') this.confirmCheckIn(st.id); });
  step(7600, 'Demo clock moves to the agreed checkout date', () => { const st = this.currentStay(); if (st) { const off = diffDays(isoOf(new Date()), st.end); this.setState({ dayOffset: off }); this.syncLedgers(off); } });
  step(9000, 'Priya records checkout', () => { const st = this.currentStay(); if (st && st.status === 'active') this.hostConfirmCheckout(st.id, { hco_date: this.today() }); });
  step(10900, 'Jordan confirms checkout', () => { const st = this.currentStay(); if (st && st.status === 'active') this.csConfirmCheckout({ co_date: this.today(), co_outcome: 'private', co_issues: '' }); });
  step(12800, 'Priya rates Jordan', () => { const d = this.latestCompletedStay(); if (d) this.hostSubmitFeedback(d.id, { host: { fbRating: 5, fbQual: ['Respect for rules', 'Tidiness'] }, forms: { hfb_text: 'A considerate guest; happy to be a reference.', hfb_recommend: true } }); });
  step(14700, 'Jordan rates Priya', () => { const d = this.latestCompletedStay(); if (d) this.csSubmitFeedback({ cs: { fbRating: 5, fbQual: ['Clear rules', 'Privacy'] }, forms: { fb_text: 'Clear rules and a quiet room. Would recommend.', fb_recommend: true } }); });
